"use client";

import { forwardRef, useId, useState, type FormEvent, type KeyboardEvent } from "react";
import { Dialog as AriaDialog, Heading, Modal, ModalOverlay } from "react-aria-components";
import { alertDialogDefaults, type AlertDialogSpecProps } from "../generated/alert-dialog.types";
import { Button } from "../button/button";
import { TextField } from "../text-field/text-field";
import { cx } from "../utils/cx";

export interface AlertDialogProps extends AlertDialogSpecProps {
  className?: string;
}

export const AlertDialog = forwardRef<HTMLElement, AlertDialogProps>(function AlertDialog(
  {
    title,
    description,
    confirmLabel = alertDialogDefaults.confirmLabel,
    cancelLabel = alertDialogDefaults.cancelLabel,
    tone = alertDialogDefaults.tone,
    confirmText,
    onConfirm,
    onCancel,
    isOpen,
    defaultOpen,
    onOpenChange,
    className,
  },
  ref,
) {
  const descriptionId = useId();
  const [pending, setPending] = useState(false);
  const [typed, setTyped] = useState("");
  const danger = tone === "danger";
  const needsText = confirmText != null && confirmText !== "";
  const matches = !needsText || typed === confirmText;

  async function confirm(close: () => void) {
    if (pending || !matches) return;
    let result: void | Promise<void>;
    try {
      result = onConfirm?.();
    } catch (error) {
      setPending(false);
      throw error;
    }
    if (result && typeof (result as Promise<void>).then === "function") {
      setPending(true);
      try {
        await result;
      } catch {
        // A failed confirm leaves the dialog open so the user can retry or cancel.
        setPending(false);
        return;
      }
      setPending(false);
    }
    close();
    setTyped("");
  }

  function cancel(close: () => void) {
    if (pending) return;
    onCancel?.();
    close();
    setTyped("");
  }

  return (
    <ModalOverlay
      isDismissable={false}
      isKeyboardDismissDisabled={pending}
      isOpen={isOpen}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[var(--rd-color-overlay-backdrop)] backdrop-blur-[2px]"
    >
      <Modal
        className={
          "w-full max-w-sm overflow-hidden [box-shadow:var(--rd-elevation-overlay)] bg-[var(--rd-color-surface-raised)] text-[var(--rd-color-text-default)] " +
          "border border-[var(--rd-color-border-default)] rounded-[var(--rd-radius-overlay)]"
        }
      >
        <AriaDialog
          ref={ref}
          role="alertdialog"
          aria-describedby={description ? descriptionId : undefined}
          className={cx("flex flex-col gap-4 p-6 outline-none", className)}
        >
          {({ close }) => (
            <form
              className="flex flex-col gap-4"
              onSubmit={(event: FormEvent) => {
                event.preventDefault();
                void confirm(close);
              }}
              onKeyDown={(event: KeyboardEvent) => {
                // The modal closes itself on Escape; report it as a cancel.
                if (event.key === "Escape" && !pending) {
                  onCancel?.();
                  setTyped("");
                }
              }}
            >
              <div className="flex flex-col gap-1">
                <Heading slot="title" className="text-lg font-semibold">
                  {title}
                </Heading>
                {description && (
                  <p id={descriptionId} className="text-sm text-[var(--rd-color-text-muted)]">
                    {description}
                  </p>
                )}
              </div>
              {needsText && (
                <TextField
                  label={`Type ${confirmText} to confirm`}
                  value={typed}
                  onChange={setTyped}
                  isDisabled={pending}
                  autoFocus={!danger}
                  autoComplete="off"
                />
              )}
              <div className="flex justify-end gap-2">
                <Button
                  type="button"
                  variant="secondary"
                  autoFocus={danger}
                  isDisabled={pending}
                  onPress={() => cancel(close)}
                >
                  {cancelLabel}
                </Button>
                <Button
                  type="submit"
                  variant={danger ? "danger" : "primary"}
                  isLoading={pending}
                  isDisabled={!matches}
                  autoFocus={!danger && !needsText}
                >
                  {confirmLabel}
                </Button>
              </div>
            </form>
          )}
        </AriaDialog>
      </Modal>
    </ModalOverlay>
  );
});

// Generated by rdloom codegen from specs/alert-dialog.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

export const alertDialogToneValues = ["default", "danger"] as const;

/** Confirmation dialog for destructive or irreversible actions. It cannot be dismissed by clicking outside, and can ask the user to type a word before the confirm button works. Open it with DialogTrigger. */
export interface AlertDialogSpecProps {
  /**
   * Heading, also the dialog's accessible name. Phrase it as the question being asked, such as Delete this user?
   */
  title: string;
  /**
   * What will happen and whether it can be undone. Wired to the dialog with aria-describedby.
   */
  description?: string;
  /**
   * Label of the confirm button. Name the action, such as Delete user.
   * @default "Confirm"
   */
  confirmLabel?: string;
  /**
   * Label of the cancel button.
   * @default "Cancel"
   */
  cancelLabel?: string;
  /**
   * Danger styles the confirm button as destructive and starts focus on the cancel button.
   * @default "default"
   */
  tone?: "default" | "danger";
  /**
   * A word the user must type exactly (such as the resource name) before the confirm button is enabled.
   */
  confirmText?: string;
  /**
   * Called when the user confirms. If it returns a promise, the confirm button shows a pending state and the dialog cannot be dismissed until it settles. The dialog closes when it resolves and stays open if it rejects.
   */
  onConfirm?: () => void | Promise<void>;
  /**
   * Called when the user cancels with the cancel button or Esc.
   */
  onCancel?: () => void;
  /**
   * Controlled open state, for dialogs opened without a DialogTrigger.
   */
  isOpen?: boolean;
  /**
   * Initial open state when uncontrolled and used without a DialogTrigger.
   */
  defaultOpen?: boolean;
  /**
   * Called when the dialog opens or closes (without a DialogTrigger).
   */
  onOpenChange?: (isOpen: boolean) => void;
}

export const alertDialogDefaults = {
  confirmLabel: "Confirm",
  cancelLabel: "Cancel",
  tone: "default",
} as const;

export const alertDialogMeta = {
  "name": "AlertDialog",
  "version": "0.1.0",
  "status": "experimental",
  "role": "alertdialog"
} as const;
